const EXPANSION_CARDS_MAP = {
  // Las 9 Expansiones de la Serie Megaevolución
  dtr: DTR_CARDS_DATA,
  "30th": ANIV30_CARDS_DATA,
  pbl: PBL_CARDS_DATA,
  cri: CRI_CARDS_DATA,
  por: POR_CARDS_DATA,
  asc: ASC_CARDS_DATA,
  pfl: PFL_CARDS_DATA,
  mep: MEP_CARDS_DATA,
  meg: MEG_CARDS_DATA,

  // Compatibilidad adicional
  pre: PRE_CARDS_DATA,
  ssp: SSP_CARDS_DATA,
  scr: SCR_CARDS_DATA,
  sfa: SFA_CARDS_DATA,
  twm: TWM_CARDS_DATA,
  tef: TEF_CARDS_DATA,
  paf: PAF_CARDS_DATA,
  par: PAR_CARDS_DATA,
  mew: MEW_CARDS_DATA,
  obf: OBF_CARDS_DATA,
  pal: PAL_CARDS_DATA,
  svi: SVI_CARDS_DATA
};

// Obtener la lista de cartas de cualquier expansión
function getCardsForExpansion(expansionId) {
  const key = (expansionId || "cri").toLowerCase();
  return EXPANSION_CARDS_MAP[key] || EXPANSION_CARDS_MAP["cri"];
}

// Obtener todas las cartas registradas de todas las expansiones
function getAllRegisteredCards() {
  let all = [];
  Object.values(EXPANSION_CARDS_MAP).forEach(cards => {
    all = all.concat(cards);
  });
  return all;
}

